<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $columns = array_values( array_filter( agum_get_columns(), static function ( $column ) { return ! empty( $column['enabled'] ) && 'password' !== $column['key']; } ) ); ?>
<div class="agum-table-responsive"><table class="agum-table"><thead><tr><th><input type="checkbox" class="agum-select-all"></th><th>Photo</th><?php foreach ( $columns as $column ) : ?><th><?php echo esc_html( $column['label'] ); ?></th><?php endforeach; ?><th>WP User</th><th>Actions</th></tr></thead><tbody>
<?php if ( empty( $users ) ) : ?><tr><td colspan="<?php echo esc_attr( count( $columns ) + 4 ); ?>" class="agum-empty">No users found.</td></tr><?php endif; ?>
<?php foreach ( (array) $users as $user ) : ?><tr data-user='<?php echo esc_attr( wp_json_encode( $user ) ); ?>'><td><input type="checkbox" class="agum-row-check" value="<?php echo esc_attr( $user->id ); ?>"></td><td><img class="agum-user-photo" src="<?php echo esc_url( ! empty( $user->profile_photo ) ? $user->profile_photo : ( ! empty( $user->image_path ) ? $user->image_path : AGUM_Upload::fallback_image_url() ) ); ?>" alt=""></td><?php foreach ( $columns as $column ) : $key = $column['key']; ?><td><?php echo esc_html( isset( $user->{$key} ) ? $user->{$key} : '' ); ?></td><?php endforeach; ?><td><?php echo $user->wp_user_id ? '<a href="' . esc_url( get_edit_user_link( $user->wp_user_id ) ) . '">#' . esc_html( $user->wp_user_id ) . '</a>' : '<span class="agum-pill">Not synced</span>'; ?></td><td><button class="agum-icon agum-edit-user">✎</button><button class="agum-icon agum-otp" data-id="<?php echo esc_attr( $user->id ); ?>">OTP</button><button class="agum-icon agum-delete-user" data-id="<?php echo esc_attr( $user->id ); ?>">🗑</button></td></tr><?php endforeach; ?>
</tbody></table></div>
